mapper.select:
select substr(add_time,1,10) as day, count(id) as orders, count(distinct user_id) as customers, sum(actual_price) as amount, round(sum(actual_price)/count(distinct user_id),2) as pcr from litemall_order
${query}
group by substr(add_time,1,10)

SELECT u.id AS grab_user_id, u.username, u.nickname, COUNT(DISTINCT o.id) AS total_grab_orders, SUM(og.number * g.water_count) AS total_water_delivered FROM litemall_order o JOIN litemall_user u ON o.grab_user_id = u.id JOIN litemall_order_goods og ON og.order_id = o.id JOIN litemall_goods g ON og.goods_id = g.id
${query}
GROUP BY o.grab_user_id ORDER BY total_grab_orders DESC;
